import { t } from '@/lib/i18n';
// Native Vue JSX. Design and behavior adapted from Beautiful UI (MIT).
import type * as UI from '@/lib/dom-types';
import { computed, type ComputedRef, type FunctionalComponent } from 'vue';
import { createComponent, createState, templateRef, watchLifecycle, cssStyle, omitProps, teleport } from '@/lib/vue-tools';
import { Button } from "@/components/atoms/Button";

/* ─────────────────────────────────────────────────────────
 * AGENT SCREEN (live viewer)
 * Watch an agent work. The resting card is a framed capture of
 * the agent's screen; hover reveals an "Open" pill (the blue
 * accent Button). Open expands to a full-width viewer where you
 * can "Teach a task" — which starts recording — collapse
 * (recording keeps running, the card shows a red REC badge), and
 * end it.
 *
 * The screen is a placeholder image by default; pass a `streamSrc`
 * (image or video URL) to pipe in a real stream.
 * ───────────────────────────────────────────────────────── */

/* Served as a static asset from /public (not Vercel Blob) so it doesn't incur
 * Blob data-transfer charges, and pre-optimized to a ~120 KB WebP (from a
 * 2.5 MB PNG) since it loads on every gallery/harness view. */
const PLACEHOLDER = "data:image/webp;base64,";

/* aspect ratio of the placeholder capture (2964×1856) — used so the collapsed
 * card shows the whole desktop with no crop */
const SCREEN_ASPECT = "aspect-[2964/1856]";
const Ico = createComponent<{
  path: UI.VNodeChild;
  size?: number;
  sw?: number;
}>("Ico", ["path", "size", "sw"], (__props, __slots) => {
  const path = computed(() => __props.path);
  const size = computed(() => __props.size === undefined ? 15 : __props.size);
  const sw = computed(() => __props.sw === undefined ? 2 : __props.sw);
  return () => {
    return <svg width={size.value} height={size.value} viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width={sw.value} stroke-linecap="round" stroke-linejoin="round" aria-hidden>
      {path.value}
    </svg>;
  };
});
/* minimize-2 — two arrows converging to the middle (collapse) */
const collapseIcon = <>
    <polyline points="4 14 10 14 10 20" />
    <polyline points="20 10 14 10 14 4" />
    <line x1="14" y1="10" x2="21" y2="3" />
    <line x1="3" y1="21" x2="10" y2="14" />
  </>;

/* maximize-2 — two arrows out to opposite corners (open) */
const openIcon = <>
    <polyline points="15 3 21 3 21 9" />
    <polyline points="9 21 3 21 3 15" />
    <line x1="21" y1="3" x2="14" y2="10" />
    <line x1="3" y1="21" x2="10" y2="14" />
  </>;
function fmt(total: number) {
  const m = Math.floor(total / 60);
  const s = total % 60;
  return `${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
}

/* macOS-style pointer */
const CursorSvg = createComponent<{
  className?: string;
  style?: UI.CSSProperties;
}>("CursorSvg", ["className", "style"], (__props, __slots) => {
  const className = computed(() => __props.className);
  const style = computed(() => __props.style);
  return () => {
    return <svg class={className.value} style={cssStyle(style.value)} width="30" height="30" viewBox="0 0 24 24" fill="#111318" stroke="#fff" stroke-width="1.4" stroke-linejoin="round" aria-hidden>
      <path d="M4.037 4.688a.495.495 0 0 1 .651-.651l16 6.5a.5.5 0 0 1-.063.947l-6.124 1.58a2 2 0 0 0-1.438 1.435l-1.579 6.126a.5.5 0 0 1-.947.063z" />
    </svg>;
  };
});
/* collapsed card: a static decorative cursor sitting on the capture */
const DriftCursor = createComponent<Record<string, never>>("DriftCursor", [], (__props, __slots) => {
  return () => {
    return <CursorSvg className="agent-cursor" style={{
      left: "42%",
      top: "53%"
    }} />;
  };
});
/* the agent's screen — a real stream via streamSrc, else a faux window.
 * Media is absolutely positioned so it always fills its (relative) parent —
 * an h-full chain through an aspect-ratio box can collapse and leak the bg. */
const Screen = createComponent<{
  streamSrc?: string;
  cursor?: boolean;
}>("Screen", ["streamSrc", "cursor"], (__props, __slots) => {
  const streamSrc = computed(() => __props.streamSrc);
  const cursor = computed(() => __props.cursor === undefined ? true : __props.cursor);
  return () => {
    return <div class="absolute inset-0 overflow-hidden bg-inset">
      {streamSrc.value ? /\.(mp4|webm|mov|m4v)(\?|$)/i.test(streamSrc.value) ? <video src={streamSrc.value} autoplay muted loop playsinline class="absolute inset-0 h-full w-full object-cover" /> :

      <img src={streamSrc.value} alt={""} class="absolute inset-0 h-full w-full object-cover" /> : <FauxWindow />}
      {cursor.value && <DriftCursor />}
    </div>;
  };
});
/* expanded viewer media — the image sizes itself within the viewport (bounded
 * by width and height) so the whole screen always fits with no crop */
const MediaSizer = createComponent<{
  src: string;
}>("MediaSizer", ["src"], (__props, __slots) => {
  const src = computed(() => __props.src);
  const style = computed(() => ({
    maxHeight: "calc(100vh - 150px)",
    maxWidth: "min(960px, 90vw)"
  }) as const);
  const cls = computed(() => "block h-auto w-auto object-contain");
  return () => {
    return /\.(mp4|webm|mov|m4v)(\?|$)/i.test(src.value) ? <video src={src.value} autoplay muted loop playsinline class={cls.value} style={cssStyle(style.value)} /> :

    <img src={src.value} alt={""} class={cls.value} style={cssStyle(style.value)} />;
  };
});
/* connecting state — spinner on black, same ring as Task Rows */
const LoadingScreen = createComponent<Record<string, never>>("LoadingScreen", [], (__props, __slots) => {
  const size = computed(() => 26),
    stroke = computed(() => 2),
    r = computed(() => (size.value - stroke.value) / 2),
    c = computed(() => 2 * Math.PI * r.value);
  return () => {
    return <div class="absolute inset-0 bg-black">
      {/* spinner dead-center; wrapper carries the centering so the spin
          transform on the svg doesn't override it */}
      <span class="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2">
        <svg width={size.value} height={size.value} class="block" style={cssStyle({
          animation: "spin 1.1s linear infinite"
        })} aria-hidden>
          <circle cx={size.value / 2} cy={size.value / 2} r={r.value} fill="none" stroke="rgba(255,255,255,0.18)" stroke-width={stroke.value} />
          <circle cx={size.value / 2} cy={size.value / 2} r={r.value} fill="none" stroke="#fff" stroke-width={stroke.value} stroke-linecap="round" stroke-dasharray={`${c.value * 0.28} ${c.value * 0.72}`} />
        </svg>
      </span>
      <span class="absolute inset-x-0 text-center text-[12.5px] font-medium text-white/70" style={cssStyle({
        top: "calc(50% + 28px)"
      })}>
        {t("agentScreen.connectingToAgentSScreen")}</span>
    </div>;
  };
});
const FauxWindow = createComponent<Record<string, never>>("FauxWindow", [], (__props, __slots) => {
  return () => {
    return <div class="flex h-full w-full flex-col bg-surface">
      <div class="flex shrink-0 items-center gap-1.5 border-b border-line bg-inset px-2.5 py-1.5">
        <span class="flex items-center gap-1">
          <span class="size-2 rounded-full bg-red" />
          <span class="size-2 rounded-full bg-orange" />
          <span class="size-2 rounded-full bg-green" />
        </span>
        <span class="ml-1 flex min-w-0 items-center gap-1.5 rounded-t-[6px] bg-surface px-2 py-1 shadow-[0_-1px_0_var(--line)]">
          <span class="size-2 shrink-0 rounded-[3px] bg-accent-tint" />
          <span class="h-1.5 w-14 rounded-full bg-line-strong" />
        </span>
      </div>
      <div class="flex shrink-0 items-center gap-2 border-b border-line px-2.5 py-1.5 text-ink-3">
        <Ico size={12} path={<path d="M15 18l-6-6 6-6" />} />
        <Ico size={12} path={<path d="M9 6l6 6-6 6" />} />
        <span class="min-w-0 flex-1 truncate rounded-full bg-field px-2.5 py-[3px] font-mono text-[9px] text-ink-3">
          {"hunter.io/try/search/ugly.cash"}</span>
      </div>
      <div class="flex flex-1 flex-col gap-2.5 overflow-hidden p-3">
        <div class="flex items-center gap-2">
          <span class="grid size-4 place-items-center rounded-[4px] bg-accent-tint text-[8px] font-bold text-accent">{"h"}</span>
          <span class="h-1.5 w-12 rounded-full bg-line-strong" />
          <span class="ml-auto h-4 w-12 rounded-full bg-inset shadow-btn" />
        </div>
        <div class="flex items-center gap-2 rounded-[8px] bg-inset p-2">
          <span class="h-3 flex-1 rounded-full bg-surface shadow-hairline" />
          <span class="h-3 w-9 rounded-full bg-accent" />
        </div>
        {["w-2/5", "w-1/2", "w-1/3", "w-2/5"].map((w, i) => <div key={i} class="flex items-center gap-2.5">
            <span class="size-6 shrink-0 rounded-full bg-accent-tint" />
            <span class="flex min-w-0 flex-1 flex-col gap-1.5">
              <span class={`h-1.5 rounded-full bg-line-strong ${w}`} />
              <span class="h-1.5 w-3/5 rounded-full bg-line" />
            </span>
          </div>)}
      </div>
    </div>;
  };
});
const AgentScreen = createComponent<{
  agentName?: string;
  streamSrc?: string;
  variant?: string;
}>("AgentScreen", ["agentName", "streamSrc", "variant"], (__props, __slots) => {
  const agentName = computed(() => __props.agentName === undefined ? t("common.agent") : __props.agentName);
  const streamSrc = computed(() => __props.streamSrc === undefined ? PLACEHOLDER : __props.streamSrc);
  const variant = computed(() => __props.variant);
  const loading = computed(() => variant.value === "Loading");
  const [open, setOpen] = createState(false);
  const [recording, setRecording] = createState(false);
  const [secs, setSecs] = createState(0);
  const [mounted, setMounted] = createState(false);
  const [cursorPos, setCursorPos] = createState<{
    x: number;
    y: number;
  } | null>(null);
  watchLifecycle(() => setMounted(true), () => []);

  // tick while recording — survives collapse (state lives here, not the overlay)
  watchLifecycle(() => {
    if (!recording.value) return;
    const id = setInterval(() => setSecs(s => s + 1), 1000);
    return () => clearInterval(id);
  }, () => [recording.value]);

  // lock scroll + Esc-to-collapse while the viewer is open
  watchLifecycle(() => {
    if (!open.value) return;
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false);
    document.addEventListener("keydown", onKey);
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = "";
    };
  }, () => [open.value]);
  const startRecording = () => {
    setSecs(0);
    setRecording(true);
  };
  const endRecording = () => {
    setRecording(false);
    setSecs(0);
  };
  const controls = computed(() => <div class="flex shrink-0 items-center gap-1.5">
      {recording.value ? <button type="button" onClick={endRecording} class="inline-flex h-[27px] items-center gap-1.5 rounded-full bg-red pl-2.5 pr-3 text-[13px] font-medium leading-none text-white shadow-[inset_0_1px_0_rgba(255,255,255,0.14)] transition-[transform,filter] duration-150 ease-out hover:brightness-95 active:scale-[0.96]">
          <span class="size-2.5 rounded-[2px] bg-white" />
          {t("agentScreen.end")}</button> : <Button variant="secondary" size="sm" className="gap-1 pl-1.5" onClick={startRecording}>
          <Ico size={15} path={<><circle cx="12" cy="12" r="9" /><circle cx="12" cy="12" r="3.5" fill="currentColor" stroke="none" /></>} />
          {t("agentScreen.teachATask")}</Button>}
      <button type="button" aria-label={t("agentScreen.collapse")} onClick={() => setOpen(false)} class="primitive-icon-button text-ink-3 transition-colors duration-100 hover:bg-hover hover:text-ink">
        <Ico size={15} path={collapseIcon} />
      </button>
    </div>);
  return () => {
    return <div class="w-full max-w-[340px]">
      {/* ── resting card — hover/click scoped to the Mac window only ── */}
      <div class={`group/screen relative ${SCREEN_ASPECT} overflow-hidden rounded-window bg-inset shadow-card transition-shadow duration-150 ${loading.value ? "" : "cursor-pointer hover:shadow-raised"}`} onClick={loading.value ? undefined : () => setOpen(true)} style={cssStyle({
        animation: "fade-up 380ms cubic-bezier(0.23,1,0.32,1) both"
      })}>
        {loading.value ? <LoadingScreen /> : <>
            <Screen streamSrc={streamSrc.value} />

            {/* hover reveal — scoped to this frame's named group, not the gallery section */}
            <div class="absolute inset-0 flex items-center justify-center bg-[rgba(17,19,24,0)] transition-colors duration-150 group-hover/screen:bg-[rgba(17,19,24,0.18)]">
              <span class="translate-y-1 opacity-0 transition duration-150 group-hover/screen:translate-y-0 group-hover/screen:opacity-100">
                <Button variant="accent" size="sm" onClick={e => {
                e.stopPropagation();
                setOpen(true);
              }}>
                  <Ico size={14} path={openIcon} />
                  {t("agentScreen.open")}</Button>
              </span>
            </div>
          </>}
      </div>

      <div class="mt-2.5 truncate px-0.5 text-[13px] font-medium text-ink">{agentName.value}{t("agentScreen.sScreen")}</div>

      {/* ── expanded viewer — portaled to <body> so it takes over the whole page ── */}
      {open.value && mounted.value && teleport(<div class="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6" role="dialog" aria-modal="true" aria-label={t("agentScreen.label0SScreen", [agentName.value])}>
            <div class="absolute inset-0 bg-black/60 dark:bg-black/75" style={cssStyle({
          animation: "fade-in 180ms ease-out both"
        })} onClick={() => setOpen(false)} />
            <div class="relative flex max-h-full flex-col overflow-hidden rounded-[16px] bg-surface p-2 pt-0 shadow-overlay" style={cssStyle({
          animation: "pop-in 240ms cubic-bezier(0.23,1,0.32,1) both"
        })}>
              {/* title bar — agent name far left, controls right */}
              <div class="flex h-11 shrink-0 items-center justify-between gap-3 px-1.5">
                <div class="flex min-w-0 items-center gap-2">
                  <span class="truncate text-[13px] font-semibold text-ink">{agentName.value}</span>
                  {recording.value && <span class="inline-flex shrink-0 items-center gap-1.5 rounded-full bg-red-tint py-0.5 pl-1.5 pr-2 text-[11.5px] font-medium tabular-nums text-red">
                      <span class="size-2 rounded-full bg-red" style={cssStyle({
                  animation: "records-pulse 1.1s ease-in-out infinite"
                })} />
                      {fmt(secs.value)}
                    </span>}
                </div>
                {controls.value}
              </div>

              {/* the screen — inset with a little padding (the crop framing);
                  the image sizes the window so the whole screen fits */}
              <div class="relative min-h-0 overflow-hidden rounded-[8px] bg-inset [cursor:none]" onMousemove={e => {
            const r = (e.currentTarget as HTMLElement).getBoundingClientRect();
            setCursorPos({
              x: e.clientX - r.left,
              y: e.clientY - r.top
            });
          }} onMouseleave={() => setCursorPos(null)}>
                {loading.value ? <div class={SCREEN_ASPECT} style={cssStyle({
              width: "min(960px, 90vw)"
            })}>
                    <LoadingScreen />
                  </div> : <MediaSizer src={streamSrc.value} />}
                {!loading.value && cursorPos.value && <CursorSvg className="pointer-events-none absolute z-10" style={{
              left: cursorPos.value.x,
              top: cursorPos.value.y,
              filter: "drop-shadow(0 1px 1.5px rgba(0,0,0,0.35))"
            }} />}
              </div>
            </div>
          </div>, document.body)}
    </div>;
  };
});
export default AgentScreen;

import { createI18n } from 'vue-i18n'
import { en, type MessageKey } from './locales/en'
import { zhCN } from './locales/zh-CN'

const messages = { en, 'zh-CN': zhCN }
export type Locale = keyof typeof messages
export type { MessageKey } from './locales/en'
const STORAGE_KEY = 'bui-locale'
function initialLocale(): Locale {
  try {
    const saved = localStorage.getItem(STORAGE_KEY)
    if (saved && Object.hasOwn(messages, saved)) return saved as Locale
  } catch { /* Storage can be disabled. */ }
  const preferred = typeof navigator === 'undefined' ? 'en' : navigator.language.toLowerCase()
  const supported = Object.keys(messages) as Locale[]
  return supported.find(code => code.toLowerCase() === preferred)
    ?? supported.find(code => code.split('-')[0] === preferred.split('-')[0])
    ?? 'en'
}

// The same Composer also serves standalone registry components without app injection.
export const i18n = createI18n({
  legacy: false,
  globalInjection: false,
  locale: initialLocale(),
  fallbackLocale: 'en',
  messages,
})
export const locale = i18n.global.locale
export function setLocale(next: Locale) {
  locale.value = next
  try { localStorage.setItem(STORAGE_KEY, next) } catch { /* Keep switching usable without storage. */ }
}

/** Stable keys for new UI copy. Params are literal data, never translated implicitly. */
export function t(key: MessageKey, params: Record<string, unknown> | unknown[] | number = {}, options: { locale?: Locale } = {}) {
  if (typeof params === 'number') return i18n.global.t(key, params, options)
  if (Array.isArray(params)) return i18n.global.t(key, params, options)
  return i18n.global.t(key, params, options)
}

import { computed, defineComponent, h, onBeforeUnmount, onMounted, shallowRef, Teleport, watch, type Component, type FunctionalComponent, type ShallowRef, type VNodeChild, type Slots, type CSSProperties, type PropType } from 'vue'

/** Declare actual Vue props and execute initialization exactly once per instance. */
export function createComponent<P>(name: string, keys: string[], setup: (props: P, slots: Slots) => () => VNodeChild, propTypes: Partial<Record<Extract<keyof P, string>, PropType<unknown>>> = {}): FunctionalComponent<Omit<P, "children"> & { children?: VNodeChild }> {
  // Explicit undefined preserves defaults resolved by the component setup.
  const types: Record<string, PropType<unknown>> = { disabled: Boolean, ...propTypes }
  return defineComponent({
    name,
    inheritAttrs: false,
    props: Object.fromEntries([...new Set([...keys, 'children', 'disabled', 'type', 'title', 'id', 'onClick', 'onPointerdown', 'onPointerup', 'onFocus', 'onBlur', 'aria-label', 'aria-expanded', 'aria-pressed', 'data-sound'])].map(key => [key, types[key] ? { type: types[key], default: undefined } : {}])),
    setup(props, { slots, attrs }) {
      const all = new Proxy(props, {
        get: (target, key) => key in target ? Reflect.get(target, key) : attrs[key as string],
        ownKeys: (target) => [...new Set([...Reflect.ownKeys(target), ...Reflect.ownKeys(attrs)])],
        getOwnPropertyDescriptor: () => ({ enumerable: true, configurable: true }),
      })
      return setup(all as P, slots)
    },
  }) as unknown as FunctionalComponent<Omit<P, "children"> & { children?: VNodeChild }>
}

export function createState<T>(initial: T | (() => T)): [ShallowRef<T>, (next: T | ((current: T) => T)) => void] {
  const state = shallowRef(typeof initial === 'function' ? (initial as () => T)() : initial) as ShallowRef<T>
  return [state, (next) => { state.value = typeof next === 'function' ? (next as (current: T) => T)(state.value) : next }]
}
export function templateRef<T>(initial: T): ShallowRef<T>;
export function templateRef<T>(initial: null): ShallowRef<T | null>;
export function templateRef<T>(initial: T | null): ShallowRef<T | null> { return shallowRef(initial) as ShallowRef<T | null> }

/** Effects run after DOM refs exist, rerun on declared reactive inputs, and dispose on unmount. */
export function watchLifecycle(effect: () => void | (() => void), sources: () => unknown[] = () => []) {
  let stop: (() => void) | undefined
  onMounted(() => {
    stop = watch(sources, (_value, _old, onCleanup) => {
      const cleanup = effect()
      if (typeof cleanup === 'function') onCleanup(cleanup)
    }, { immediate: true, flush: 'post' })
  })
  onBeforeUnmount(() => stop?.())
}

const unitless = new Set(['animationIterationCount', 'aspectRatio', 'borderImageOutset', 'borderImageSlice', 'borderImageWidth', 'columnCount', 'flex', 'flexGrow', 'flexShrink', 'fontWeight', 'gridArea', 'gridColumn', 'gridColumnEnd', 'gridColumnStart', 'gridRow', 'gridRowEnd', 'gridRowStart', 'lineHeight', 'opacity', 'order', 'orphans', 'scale', 'tabSize', 'widows', 'zIndex', 'zoom', 'fillOpacity', 'strokeDashoffset', 'strokeOpacity', 'strokeWidth'])
export function cssStyle(style: unknown): CSSProperties {
  if (!style || typeof style !== 'object') return style as CSSProperties
  return Object.fromEntries(Object.entries(style).map(([key, value]) => [key, typeof value === 'number' && value !== 0 && !key.startsWith('--') && !unitless.has(key) ? `${value}px` : value])) as CSSProperties
}
export function omitProps<P extends object>(props: P, names: string[]) { return Object.fromEntries(Object.entries(props).filter(([key]) => !names.includes(key))) }
export function teleport(children: VNodeChild, target: Element | string) { return h(Teleport, { to: target }, children as never) }

// Native Vue JSX. Design and behavior adapted from Beautiful UI (MIT).
import type * as UI from '@/lib/dom-types';
import { computed, type ComputedRef, type FunctionalComponent } from 'vue';
import { createComponent, createState, templateRef, watchLifecycle, cssStyle, omitProps, teleport } from '@/lib/vue-tools';
import type { ButtonHTMLAttributes } from '@/lib/dom-types';
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
const filledShadow = "shadow-[inset_0_1px_0_rgba(255,255,255,0.14)]";

/* Pill-shaped by default — the app's core button style. Explicit symmetric
 * padding (not a fixed height) so the top/bottom spacing is always equal. */
export const buttonVariants = cva(`inline-flex items-center justify-center font-medium select-none
   transition-[transform,background-color,opacity] duration-150 ease-out
   active:scale-[0.96] disabled:opacity-50 disabled:pointer-events-none`, {
  variants: {
    variant: {
      primary: `bg-ink text-canvas hover:opacity-90 dark:bg-ink dark:text-canvas ${filledShadow}`,
      secondary: "bg-surface text-ink shadow-btn hover:bg-inset aria-expanded:bg-hover",
      ghost: "bg-hover-2 text-ink hover:bg-line-strong",
      accent: `bg-accent text-white hover:bg-accent-ink ${filledShadow}`,
      success: `bg-green text-white hover:brightness-95 ${filledShadow}`,
      /* transparent until hovered — for dense toolbars/action rows */
      quiet: "text-ink hover:bg-hover"
    },
    size: {
      /* compact toolbar pill — fixed height, lighter weight */
      xs: "h-7 rounded-full px-2.5 text-[12px] font-normal leading-none gap-1",
      /* canonical action pill — 27px tall, roomy sides */
      sm: "h-[27px] px-3 text-[13px] leading-none rounded-full gap-1.5",
      md: "px-4 py-[9px] text-sm leading-none rounded-full gap-2"
    }
  },
  defaultVariants: {
    variant: "secondary",
    size: "md"
  }
});
export type ButtonVariant = NonNullable<VariantProps<typeof buttonVariants>["variant"]>;
export const Button = createComponent<ButtonHTMLAttributes<HTMLButtonElement> & VariantProps<typeof buttonVariants>>("Button", ["variant", "size", "className"], (__props, __slots) => {
  const variant = computed(() => __props.variant);
  const size = computed(() => __props.size);
  const className = computed(() => __props.className);
  const props = computed(() => omitProps(__props, ["variant", "size", "className", "children"]));
  return () => {
    return <button class={cn(buttonVariants({
      variant: variant.value,
      size: size.value
    }), className.value)} {...props.value}>{__slots.default?.() ?? __props.children}</button>;
  };
});

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'
export function cn(...inputs: ClassValue[]) { return twMerge(clsx(inputs)) }

@import "tailwindcss";
/* shadow-plugin (flornkm) — smooth, layered shadow stacks. The unprefixed
 * entry maps them onto Tailwind's --shadow-xs…2xl scale; our semantic tokens
 * below build on those values so the whole app picks up the smooth shadows. */
@import "shadow-plugin/unprefixed";

@custom-variant dark (&:where(.dark, .dark *));

/* GENERIC FOUNDATION — tokens, @theme, base rules, the primitive-*
 * spacing utilities, and shared keyframes below are needed by EVERY
 * component. Blocks tagged COMPONENT-SPECIFIC further down belong to
 * one primitive each. */
/* ──────────────────────────────────────────────────────────
 * Beautiful UI — design tokens
 * Cool near-white canvas, white cards, hairline borders, layered
 * single-digit-opacity shadows, a neutral ink ramp, and semantic
 * color used sparingly as a condiment.
 * ────────────────────────────────────────────────────────── */

:root {
  /* Native controls and all inherited scrollbars follow the active theme. */
  color-scheme: light;
  scrollbar-color: var(--line-strong) transparent;
  /* surfaces — cool, blue-tinted neutrals */
  --page: oklch(0.985 0.001 286.376);
  --canvas: oklch(0.961 0.002 247.84);
  --surface: oklch(1 0 0);
  --inset: oklch(0.979 0.002 247.839);
  --hover: oklch(0.97 0.002 247.839);
  --hover-2: oklch(0.933 0.003 247.86);

  /* ink ramp */
  --ink: oklch(0.247 0.006 258.361);
  --ink-2: oklch(0.506 0.01 264.477);
  --ink-3: oklch(0.695 0.009 264.505);

  /* borders — solid and crisp, not alpha */
  --line: oklch(0.946 0.003 264.542);
  --line-strong: oklch(0.912 0.005 258.326);
  --line-soft: oklch(0.966 0.002 264.542);
  --grid-line: color-mix(in srgb, var(--line) 78%, transparent);
  --field: oklch(0.961 0.001 286.375);
  --stripe: oklch(0.405 0 0 / 0.075);
  --stripe-bg: oklch(0.97 0 0);

  /* accent */
  --accent: oklch(0.626 0.205 254.947);
  --accent-ink: oklch(0.556 0.187 255.617);
  --accent-tint: oklch(0.96 0.019 252.878);

  /* semantic */
  --green: oklch(0.603 0.155 150.883);
  --green-tint: oklch(0.958 0.017 159.118);
  --orange: oklch(0.689 0.179 49.902);
  --orange-tint: oklch(0.964 0.021 67.581);
  --red: oklch(0.621 0.192 23.042);
  --red-tint: oklch(0.956 0.017 17.462);

  /* chart overlays — neutral system colors with enough contrast on either theme */
  --tooltip-bg: oklch(0.272 0.008 264.435);
  --tooltip-fg: oklch(0.976 0.002 247.839);
  --tooltip-muted: oklch(0.731 0.008 260.731);
  --tooltip-border: oklch(0.356 0.007 264.474);

  /* shadows — our solid hairline ring + shadow-plugin's smooth layered stacks
   * (--shadow-xs…lg come from shadow-plugin/unprefixed) so every surface reads
   * consistently across the app. */
  --shadow-hairline: 0 0 0 1px var(--line);
  --shadow-btn: 0 0 0 1px var(--line-strong), var(--shadow-xs);
  --shadow-card: 0 0 0 1px var(--line), var(--shadow-sm);
  --shadow-raised: 0 0 0 1px var(--line), var(--shadow-md);
  --shadow-overlay: 0 0 0 1px var(--line), var(--shadow-lg);
  --shadow-inset-field: inset 0 1px 2px oklch(0 0 0 / 0.12);
}

.dark {
  color-scheme: dark;
  --page: oklch(0.209 0.004 264.477);
  --canvas: oklch(0.231 0.004 264.487);
  --surface: oklch(0.26 0.006 271.191);
  --inset: oklch(0.243 0.004 264.492);
  --hover: oklch(0.289 0.006 271.22);
  --hover-2: oklch(0.318 0.007 274.747);

  --ink: oklch(0.964 0.002 247.839);
  --ink-2: oklch(0.731 0.008 260.731);
  --ink-3: oklch(0.541 0.01 264.484);

  --line: oklch(0.308 0.006 258.354);
  --line-strong: oklch(0.356 0.007 264.474);
  --line-soft: oklch(0.278 0.006 258.354);
  --field: oklch(0.293 0.006 271.223);
  --stripe: oklch(1 0 0 / 0.055);
  --stripe-bg: oklch(0.226 0.004 264.485);

  --accent: oklch(0.68 0.173 253.301);
  --accent-ink: oklch(0.788 0.113 248.33);
  --accent-tint: oklch(0.68 0.173 253.301 / 0.16);

  --green: oklch(0.705 0.154 153.814);
  --green-tint: oklch(0.705 0.154 153.814 / 0.14);
  --orange: oklch(0.746 0.156 55.642);
  --orange-tint: oklch(0.746 0.156 55.642 / 0.14);
  --red: oklch(0.666 0.18 21.433);
  --red-tint: oklch(0.666 0.18 21.433 / 0.14);

  --tooltip-bg: oklch(0.182 0.004 264.459);
  --tooltip-fg: oklch(0.964 0.002 247.839);
  --tooltip-muted: oklch(0.731 0.008 260.731);
  --tooltip-border: oklch(0.308 0.006 258.354);

  --shadow-hairline: 0 0 0 1px var(--line);
  /* Elevation rings go to a subtle *light* hairline in dark mode: the ring
   * paints over the surface behind the element, so a low-alpha white edge
   * dissolves into the shadow as one continuous stroke (per smooth-shadow-ring),
   * graduated by how far the surface floats. */
  --shadow-btn: 0 0 0 1px oklch(1 0 0 / 0.1), 0 1px 2px oklch(0 0 0 / 0.3);
  --shadow-card:
    0 0 0 1px oklch(1 0 0 / 0.11), 0 1px 2px oklch(0 0 0 / 0.2),
    0 2px 6px oklch(0 0 0 / 0.2);
  --shadow-raised:
    0 0 0 1px oklch(1 0 0 / 0.13), 0 2px 10px oklch(0 0 0 / 0.22);
  --shadow-overlay:
    0 0 0 1px oklch(1 0 0 / 0.15), 0 8px 28px oklch(0 0 0 / 0.34);
  --shadow-inset-field: inset 0 1px 2px oklch(0 0 0 / 0.4);
}

@theme inline {
  /* colors */
  --color-page: var(--page);
  --color-canvas: var(--canvas);
  --color-surface: var(--surface);
  --color-inset: var(--inset);
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-ink-3: var(--ink-3);
  --color-hover: var(--hover);
  --color-hover-2: var(--hover-2);
  --color-field: var(--field);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-accent: var(--accent);
  --color-accent-ink: var(--accent-ink);
  --color-accent-tint: var(--accent-tint);
  --color-green: var(--green);
  --color-green-tint: var(--green-tint);
  --color-orange: var(--orange);
  --color-orange-tint: var(--orange-tint);
  --color-red: var(--red);
  --color-red-tint: var(--red-tint);

  /* shadows */
  --shadow-hairline: var(--shadow-hairline);
  --shadow-btn: var(--shadow-btn);
  --shadow-inset-field: var(--shadow-inset-field);
  --shadow-card: var(--shadow-card);
  --shadow-raised: var(--shadow-raised);
  --shadow-overlay: var(--shadow-overlay);

  /* type */
  --font-sans: var(--font-inter), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-mono-face), ui-monospace, "SF Mono", monospace;

  /* radii — chips 6, controls 8, cards 10, windows 14, pills 999 */
  --radius-chip: 6px;
  --radius-control: 8px;
  --radius-card: 10px;
  --radius-window: 14px;

  /* easing — strong curves; built-ins are too weak */
  --ease-out-strong: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-in-out-strong: cubic-bezier(0.77, 0, 0.175, 1);
  --ease-link: cubic-bezier(0.16, 1, 0.3, 1);
}

/* ── base ─────────────────────────────────────────────── */

html {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

body {
  background-color: var(--stripe-bg);
  background-image: repeating-linear-gradient(
    -45deg,
    transparent 0,
    transparent 7px,
    var(--stripe) 7px,
    var(--stripe) 8px
  );
  /* Pin the stripe pattern to the viewport so it stays put on scroll. */
  background-attachment: fixed;
  color: var(--ink);
  font-feature-settings: "cv11", "ss01";
  font-size: 14px;
  letter-spacing: -0.01em;
  line-height: 1.5;
}

::selection {
  background: var(--accent-tint);
  color: var(--ink);
}

/* ── interface hygiene (interfaces.dev cheat sheet) ────── */

/* headings balance; descriptions avoid orphans (skip long-form — we have none) */
h1,
h2,
h3,
h4 {
  text-wrap: balance;
}

p {
  text-wrap: pretty;
}

/* underlines clear descenders */
a {
  text-underline-position: from-font;
  text-decoration-skip-ink: auto;
}

/* theme switches swap every token at once — freeze transitions so the flip
 * is one clean repaint instead of hundreds of mismatched color fades */
.theme-switching *,
.theme-switching *::before,
.theme-switching *::after {
  transition: none !important;
}

/* touch: :hover sticks after a tap, so neutralize row/header hovers there */
@media (hover: none) {
  .records-row:hover > .records-cell {
    background: transparent;
  }

  .records-row:hover > td.is-colsel {
    background: color-mix(in srgb, var(--accent) 4%, var(--surface));
  }

  .records-header-button:hover {
    background: transparent;
    color: var(--ink-2);
  }
}

/* Chat overflow uses the same neutral tokens as the surrounding interface. */
.chat-thread-scroll {
  color-scheme: light;
  scrollbar-width: thin;
  scrollbar-color: var(--line-strong) transparent;
}
.dark .chat-thread-scroll {
  color-scheme: dark;
}
.chat-thread-scroll::-webkit-scrollbar {
  width: 6px;
}
.chat-thread-scroll::-webkit-scrollbar-track {
  background: transparent;
}
.chat-thread-scroll::-webkit-scrollbar-thumb {
  background: var(--line-strong);
  border-radius: 999px;
}
.chat-thread-scroll::-webkit-scrollbar-thumb:hover {
  background: var(--ink-3);
}

/* Keep the component nav scrollable but hide its scrollbar. */
.component-nav-scroll {
  scrollbar-width: none; /* Firefox */
  -ms-overflow-style: none; /* legacy Edge */
}
.component-nav-scroll::-webkit-scrollbar {
  display: none; /* WebKit */
}

@media (min-width: 64rem) {
  .component-nav-scroll {
    -webkit-mask-image: linear-gradient(
      to bottom,
      oklch(0 0 0) 0,
      oklch(0 0 0) calc(100% - 6rem),
      transparent 100%
    );
    mask-image: linear-gradient(
      to bottom,
      oklch(0 0 0) 0,
      oklch(0 0 0) calc(100% - 6rem),
      transparent 100%
    );
  }
}

/* Mobile demo gestures should operate controls and visualizations rather than
 * selecting surrounding labels. Text entry and code remain intentionally
 * selectable. */
@media (hover: none) and (pointer: coarse) {
  .primitive-showcase {
    -webkit-user-select: none;
    user-select: none;
    -webkit-touch-callout: none;
  }

  .primitive-showcase :is(input, textarea, [contenteditable="true"], pre, code) {
    -webkit-user-select: text;
    user-select: text;
    -webkit-touch-callout: default;
  }

  .primitive-showcase :is(a, button, [role="button"]) {
    -webkit-tap-highlight-color: transparent;
  }

  .primitive-showcase :is(a, button, [role="button"]):focus-visible {
    outline: none;
  }

  .primitive-showcase :is(img, svg, canvas) {
    -webkit-user-drag: none;
  }

  .insight-chart-stage {
    touch-action: pan-y;
  }
}

/* Tailwind v4 resets buttons to cursor:default — anything
 * clickable must invite the click */
button:not(:disabled),
[role="button"]:not([aria-disabled="true"]),
label:has(input),
a {
  cursor: pointer;
}


:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

input:focus-visible,
textarea:focus-visible,
select:focus-visible,
[contenteditable]:focus-visible {
  outline: none;
}

.animated-underline {
  position: relative;
  display: inline-block;
}

.animated-underline::after {
  position: absolute;
  right: 0;
  bottom: -1px;
  left: 0;
  height: 1px;
  content: "";
  background: currentColor;
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 280ms var(--ease-link);
}

a:hover .animated-underline::after,
a:focus-visible .animated-underline::after {
  transform: scaleX(1);
}

/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — StreamingText / ContextCards
 * Favicon source avatars.
 * Copy this block only alongside StreamingText / ContextCards; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.source-avatar {
  box-shadow: 0 0 0 1px oklch(0.21 0.034 263.436 / 0.1);
}

.dark .source-avatar {
  box-shadow: 0 0 0 1px oklch(1 0 0 / 0.08);
}

/* ── primitive spacing system ─────────────────────────────
 * Shared optical offsets for small demo cards. Use these
 * instead of hand-tuning 10/12/14px per component.
 */

.primitive-card-pad {
  padding: 12px;
}

.primitive-card-bar {
  padding: 10px 12px;
}

.primitive-card-footer {
  padding: 10px;
}

.primitive-table-cell {
  padding: 10px 12px;
}

.primitive-icon-button {
  display: inline-flex;
  width: 28px;
  height: 28px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-control);
}

/* ── shared keyframes ─────────────────────────────────── */

@keyframes shimmer-text {
  from {
    background-position: 150% center;
  }
  to {
    background-position: -50% center;
  }
}

@keyframes fade-up {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.home-reveal {
  will-change: opacity, transform, filter;
}

/* The sidebar is one persistent 224px tree clipped by a 52px shell.
 * Every rail glyph remains centered at x=26 in both states. */
/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — SidebarNav
 * The 52↔224px collapsible sidebar tree.
 * Copy this block only alongside SidebarNav; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.sidebar-row {
  width: 208px;
  transition-duration: var(--sidebar-copy-duration);
  transition-timing-function: var(--sidebar-easing);
}

.sidebar-copy {
  opacity: 1;
  transform: translateX(0);
  transition:
    opacity var(--sidebar-copy-duration) ease-out,
    transform var(--sidebar-copy-duration) var(--sidebar-easing);
}

.sidebar-logo,
.sidebar-collapse-control,
.sidebar-expand-control {
  transition-duration: var(--sidebar-copy-duration);
  transition-timing-function: ease-out;
}

.sidebar-expand-control {
  pointer-events: none;
  opacity: 0;
}

.sidebar-glide-highlight {
  right: 8px;
  left: 8px;
}

[data-sidebar-collapsed="true"] .sidebar-row {
  width: 36px;
}

[data-sidebar-collapsed="true"] .sidebar-copy {
  pointer-events: none;
  opacity: 0;
  transform: translateX(calc(var(--sidebar-copy-offset) * -1));
}

[data-sidebar-collapsed="true"] .sidebar-workspace-control {
  pointer-events: none;
}

[data-sidebar-collapsed="true"] .sidebar-logo,
[data-sidebar-collapsed="true"] .sidebar-collapse-control {
  pointer-events: none;
  opacity: 0;
}

[data-sidebar-collapsed="true"] .sidebar-expand-control {
  pointer-events: auto;
  opacity: 1;
}

[data-sidebar-collapsed="true"] .sidebar-glide-highlight {
  right: auto;
  width: 36px;
}

@media (prefers-reduced-motion: reduce) {
  .home-reveal {
    opacity: 1 !important;
    transform: none !important;
    filter: none !important;
  }
}

/* ── records table ────────────────────────────────────────
 * The grid is deliberately more architectural than card-like:
 * one quiet surface, precise rules, and color reserved for
 * meaning. The first column remains an anchor while both axes
 * can move independently inside the table viewport.
 */

/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — RecordsTable
 * The full CRM grid, spreadsheet gutter, and AI column (~800 lines).
 * Copy this block only alongside RecordsTable; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.records-shell {
  width: 100%;
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--surface);
  box-shadow: 0 1px 2px oklch(0 0 0 / 0.06);
}

/* fill mode: the shell stretches to fill its container and drops its own
 * border/radius/shadow so it reads as part of the surrounding card rather
 * than a container-in-a-container. The grid body flexes to fill height. */
.records-shell.is-fill {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  height: 100%;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}

.records-shell.is-fill .records-scroll {
  max-height: none;
  flex: 1;
}

.records-toolbar {
  display: flex;
  min-height: 52px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--line-strong);
  background: var(--surface);
}

.records-toolbar-left,
.records-toolbar-right,
.records-company-header,
.records-quiet-button,
.records-secondary-button,
.records-primary-button,
.records-select-button,
.records-strength,
.records-link,
.records-add-calculation {
  display: inline-flex;
  align-items: center;
}

.records-toolbar-left,
.records-toolbar-right {
  gap: 4px;
}

.records-toolbar-right {
  flex-shrink: 0;
}

.records-select-button,
.records-quiet-button,
.records-secondary-button,
.records-primary-button {
  height: 32px;
  gap: 7px;
  border-radius: var(--radius-control);
  padding: 0 10px;
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
  transition: background-color 140ms var(--ease-out-strong), color 140ms var(--ease-out-strong), transform 140ms var(--ease-out-strong), box-shadow 140ms var(--ease-out-strong);
}

.records-select-button {
  gap: 8px;
  color: var(--ink);
  border: 1px solid var(--line);
  background: var(--surface);
}

.records-select-button:hover,
.records-quiet-button:hover,
.records-secondary-button:hover {
  background: var(--hover);
  color: var(--ink);
}

.records-quiet-button {
  color: var(--ink-2);
}

.records-quiet-button.is-active {
  background: var(--accent-tint);
  color: var(--accent-ink);
}

.records-secondary-button {
  border: 1px solid var(--tooltip-border);
  color: var(--ink-2);
  box-shadow: none;
}

.records-primary-button {
  margin-left: 3px;
  background: var(--accent);
  color: oklch(1 0 0);
  box-shadow: none;
}

.records-primary-button:hover {
  filter: saturate(0.9) brightness(1.04);
}

.records-quiet-button:active,
.records-secondary-button:active,
.records-primary-button:active,
.records-select-button:active,
.records-add-calculation:active {
  transform: scale(0.96);
}

.records-database-icon {
  display: inline-flex;
  color: var(--green);
}

.records-filter-wrap {
  position: relative;
}

.records-filter-dot {
  width: 5px;
  height: 5px;
  margin-left: -2px;
  border-radius: 99px;
  background: var(--accent);
}

.records-filter-menu {
  position: absolute;
  z-index: 30;
  top: calc(100% + 7px);
  left: 0;
  width: 190px;
  padding: 6px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-card);
  background: var(--surface);
  box-shadow: var(--shadow-overlay);
  animation: pop-in 160ms var(--ease-out-strong) both;
  transform-origin: top left;
}

.records-sort-menu {
  left: -48px;
}

.records-filter-label {
  padding: 5px 8px 6px;
  color: var(--ink-3);
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.records-filter-menu button {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 7px;
  border-radius: var(--radius-chip);
  padding: 7px 8px;
  color: var(--ink-2);
  font-size: 12px;
  text-align: left;
  transition: background-color 120ms ease-out, color 120ms ease-out;
}

.records-filter-menu button:hover,
.records-filter-menu button.is-selected {
  background: var(--hover);
  color: var(--ink);
}

.records-menu-check {
  width: 13px;
  color: var(--accent-ink);
  font-size: 12px;
  font-weight: 500;
  text-align: center;
}

.records-scroll {
  max-height: 438px;
  overflow: auto;
  overscroll-behavior: none;
  scrollbar-color: var(--line-strong) transparent;
  scrollbar-gutter: stable;
}

.records-scroll:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

.records-table {
  width: 100%;
  min-width: 990px;
  border-collapse: separate;
  border-spacing: 0;
  color: var(--ink);
  font-size: 13px;
  font-weight: 500;
  table-layout: fixed;
}

.records-company-col { width: 270px; }
.records-category-col { width: 275px; }
.records-last-col { width: 190px; }
.records-strength-col { width: 210px; }
.records-link-col { width: 175px; }

.records-table th,
.records-table td {
  border-right: 1px solid color-mix(in srgb, var(--line) 78%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--line) 78%, transparent);
  text-align: left;
  vertical-align: middle;
}

.records-table tr > :last-child {
  border-right: 0;
}

.records-table thead th {
  position: sticky;
  z-index: 5;
  top: 0;
  height: 35px;
  background: var(--surface);
  color: var(--ink-2);
  font-size: 12.5px;
  font-weight: 500;
}

.records-header-cell {
  padding: 0;
}

.records-resize-handle {
  position: absolute;
  z-index: 12;
  top: 0;
  right: -6px;
  width: 12px;
  height: 100%;
  cursor: col-resize;
  touch-action: none;
}

.records-resize-handle::after {
  position: absolute;
  top: 7px;
  bottom: 7px;
  left: 5px;
  width: 2px;
  border-radius: 99px;
  background: var(--accent);
  content: "";
  opacity: 0;
  transform: scaleY(0.65);
  transition: opacity 120ms ease-out, transform 150ms var(--ease-out-strong);
}

.records-resize-handle:hover::after,
.records-resize-handle.is-resizing::after {
  opacity: 1;
  transform: scaleY(1);
}

.records-header-cell.records-sticky-cell {
  z-index: 7;
}

.records-header-button,
.records-company-header {
  width: 100%;
  height: 35px;
  gap: 8px;
  padding: 0 12px;
}

.records-company-header {
  padding-left: 6px;
}

.records-header-button {
  display: flex;
  align-items: center;
  color: var(--ink-2);
  text-align: left;
  transition: background-color 120ms ease-out, color 120ms ease-out;
}

.records-header-button:hover {
  background: var(--hover);
  color: var(--ink);
}

.records-header-icon {
  display: inline-flex;
  flex-shrink: 0;
  color: var(--ink-3);
}

.records-sort {
  display: inline-flex;
  flex-shrink: 0;
  margin-left: auto;
  opacity: 0;
  transition: opacity 120ms ease-out, transform 160ms var(--ease-out-strong);
}

.records-header-button:hover .records-sort,
.records-sort.is-visible {
  opacity: 1;
}

.records-company-header {
  display: flex;
}

.records-company-header > span:not(.records-checkbox-box) {
  white-space: nowrap;
}

.records-add-field {
  display: inline-flex;
  margin-left: auto;
  color: var(--ink-3);
  opacity: 0;
  transition: opacity 120ms ease-out, color 120ms ease-out;
}

.records-company-header:hover .records-add-field,
.records-add-field:focus-visible {
  opacity: 1;
}

.records-add-field:hover {
  color: var(--ink);
}

.records-checkbox {
  position: relative;
  display: inline-flex;
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-chip);
}

.records-checkbox input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}

.records-checkbox-box {
  display: inline-flex;
  width: 18px;
  height: 18px;
  align-items: center;
  justify-content: center;
  border: 1px solid oklch(0.845 0.011 247.953);
  border-radius: 6px;
  color: oklch(0.446 0.018 251.343);
  background: oklch(1 0 0);
  transition: border-color 140ms ease-out, background-color 140ms ease-out, box-shadow 140ms ease-out, transform 140ms var(--ease-out-strong);
}

.records-checkbox:hover .records-checkbox-box {
  border-color: oklch(0.773 0.016 251.194);
  background: oklch(0.966 0.003 228.784);
}

.records-checkbox:active .records-checkbox-box {
  transform: scale(0.96);
}

.records-checkbox input:focus-visible + .records-checkbox-box {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.records-checkbox-box.is-active {
  border-color: var(--accent);
  color: oklch(1 0 0);
  background: var(--accent);
  box-shadow: none;
}

.records-checkbox-dash {
  width: 8px;
  height: 1.5px;
  border-radius: 99px;
  background: oklch(1 0 0);
}

.dark .records-checkbox-box {
  border-color: oklch(0.45 0.017 254.711);
  color: oklch(0.917 0.007 247.901);
  background: oklch(0.346 0.015 252.294);
}

.dark .records-checkbox:hover .records-checkbox-box {
  border-color: oklch(0.521 0.019 254);
  background: oklch(0.391 0.016 251.761);
}

.dark .records-checkbox-box.is-active {
  border-color: var(--accent);
  color: oklch(1 0 0);
  background: var(--accent);
}

.dark .records-checkbox-dash {
  background: oklch(1 0 0);
}

.records-cell {
  height: 35px;
  padding: 0 8px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.records-sticky-cell {
  position: sticky;
  left: 0;
  z-index: 2;
  background: var(--surface);
  box-shadow: 5px 0 8px -10px oklch(0 0 0 / 0.4);
}

.records-company-cell {
  display: flex;
  align-items: center;
  gap: 4px;
  padding-left: 6px;
  overflow: visible;
}

.records-row > .records-cell {
  transition: background-color 120ms ease-out, color 120ms ease-out;
}

.records-row:hover > .records-cell {
  background: var(--hover);
}

.records-row.is-selected > .records-cell {
  background: color-mix(in srgb, var(--accent) 7%, var(--surface));
}

/* ── spreadsheet gutter ──────────────────────────────────
 * Row numbers at rest; the checkbox takes their place on
 * hover or once the row is selected. */
.records-rownum {
  display: inline-flex;
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  align-items: center;
  justify-content: center;
  color: var(--ink-3);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
}

.records-row .records-checkbox {
  display: none;
}

.records-row:hover .records-rownum,
.records-row.is-selected .records-rownum {
  display: none;
}

.records-row:hover .records-checkbox,
.records-row.is-selected .records-checkbox {
  display: inline-flex;
}

/* ── selected column — the property being configured ───── */
.records-table th.is-colsel {
  background: color-mix(in srgb, var(--accent) 8%, var(--surface));
  box-shadow: inset 0 2px 0 var(--accent);
}

th.is-colsel .records-header-button,
th.is-colsel .records-company-header,
th.is-colsel .records-header-icon {
  color: var(--accent-ink);
}

.records-table td.is-colsel {
  background: color-mix(in srgb, var(--accent) 4%, var(--surface));
}

.records-row:hover > td.is-colsel {
  background: color-mix(in srgb, var(--accent) 8%, var(--surface));
}

.records-row.is-selected > td.is-colsel {
  background: color-mix(in srgb, var(--accent) 10%, var(--surface));
}

/* ── AI column calculating state ─────────────────────────── */
.records-calc {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.records-pulse {
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 50%;
  background: var(--accent);
  animation: records-pulse 1.1s ease-in-out infinite;
}

@keyframes records-pulse {
  0%,
  100% {
    opacity: 0.35;
    transform: scale(0.8);
  }
  50% {
    opacity: 1;
    transform: scale(1);
  }
}

/* agent-screen — a static decorative cursor sitting on the capture (for show) */
.agent-cursor {
  position: absolute;
  pointer-events: none;
  filter: drop-shadow(0 1px 1.5px rgba(0, 0, 0, 0.35));
}

.records-company-mark {
  display: inline-flex;
  width: 20px;
  height: 20px;
  flex: 0 0 20px;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 6px;
  color: var(--ink-2);
  background: var(--field);
  font-size: 10px;
  font-weight: 500;
}

.records-company-name {
  min-width: 0;
  overflow: hidden;
  color: var(--ink);
  font-size: 13px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.records-company-name.has-link:hover,
.records-company-name.has-link:focus-visible {
  color: var(--accent-ink);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.records-tags {
  position: relative;
  display: flex;
  width: 100%;
  min-width: 0;
  align-items: center;
  gap: 4px;
  overflow: hidden;
}

.records-tags-measure {
  position: absolute;
  top: 0;
  left: 0;
  display: flex;
  width: max-content;
  gap: 4px;
  pointer-events: none;
  visibility: hidden;
}

.records-tags-measure > span {
  display: inline-flex;
}

.records-tag {
  display: inline-flex;
  height: 23px;
  max-width: 115px;
  align-items: center;
  flex-shrink: 0;
  overflow: hidden;
  cursor: pointer;
  border: 1px solid color-mix(in srgb, var(--tag-base) 32%, var(--surface));
  border-radius: 8px;
  padding: 0 7px;
  color: color-mix(in srgb, var(--tag-base) 92%, var(--ink));
  background: color-mix(in srgb, var(--tag-base) 18%, var(--surface));
  font-size: 13px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.records-more-tag {
  display: inline-flex;
  height: 23px;
  align-items: center;
  flex-shrink: 0;
  border: 1px solid var(--line-strong);
  border-radius: 6px;
  padding: 0 7px;
  color: var(--ink-3);
  background: var(--inset);
  font-size: 11px;
  font-weight: 500;
}

.records-more-tag {
  border-color: var(--line-strong);
  color: var(--ink-3);
  background: var(--inset);
}

.records-muted {
  color: var(--ink-3);
}

.records-strength {
  gap: 8px;
  color: var(--ink-2);
}

.records-strength-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 50%;
}

.records-link {
  max-width: 100%;
  gap: 5px;
  overflow: hidden;
  color: var(--accent-ink);
  text-overflow: ellipsis;
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, currentColor 35%, transparent);
  text-underline-offset: 3px;
  transition: color 120ms ease-out, text-decoration-color 120ms ease-out;
}

.records-link-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.records-link svg {
  flex-shrink: 0;
}

.records-link:hover,
.records-link:focus-visible {
  color: var(--ink);
  text-decoration-color: currentColor;
}

.records-table tfoot td {
  position: sticky;
  z-index: 4;
  bottom: 0;
  height: 35px;
  background: var(--inset);
  color: var(--ink-2);
  font-size: 14px;
  font-weight: 500;
  line-height: 1;
}

.records-table tfoot .records-sticky-cell {
  z-index: 6;
  background: var(--inset);
}

.records-calculation-label {
  color: var(--ink-2);
  font-weight: 500;
}

.records-footer-value {
  display: inline-flex;
  height: 35px;
  align-items: center;
  vertical-align: middle;
}

.records-calculation-number {
  margin-right: 3px;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.records-add-calculation {
  height: 35px;
  gap: 6px;
  color: var(--ink-3);
  font-size: 14px;
  font-weight: 500;
  line-height: 1;
  transition: color 120ms ease-out, transform 140ms var(--ease-out-strong);
}

.records-add-calculation:hover {
  color: var(--ink);
}

.records-average {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--ink-2);
}

.records-calculation-row-secondary td {
  position: sticky;
  bottom: 35px;
  background: color-mix(in srgb, var(--inset) 70%, var(--surface));
}

.records-calculation-row-secondary .records-sticky-cell {
  position: sticky;
  background: color-mix(in srgb, var(--inset) 70%, var(--surface));
}

.records-footer {
  display: flex;
  min-height: 35px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0 12px;
  color: var(--ink-3);
  font-size: 11.5px;
}

.records-footer strong {
  color: var(--ink-2);
  font-weight: 500;
}

.records-footer-hint {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  opacity: 0;
  transition: opacity 160ms ease-out;
}

.records-shell:hover .records-footer-hint {
  opacity: 1;
}

.records-scroll-cue {
  display: inline-flex;
  color: var(--ink-3);
}

@media (max-width: 640px) {
  .records-toolbar {
    align-items: flex-start;
    flex-direction: column;
  }

  .records-toolbar-left,
  .records-toolbar-right {
    width: 100%;
  }

  .records-toolbar-right {
    justify-content: flex-end;
  }

  .records-footer-hint {
    display: none;
  }
}

/* ── filter table electric status colors ─────────────────── */

/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — FilterTable
 * Electric status-pill colors.
 * Copy this block only alongside FilterTable; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.filter-status-todo,
.filter-status-progress,
.filter-status-done {
  border: 1px solid transparent;
}

/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — InsightCards
 * Liveline chart tooltip + cursor.
 * Copy this block only alongside InsightCards; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.insight-chart-stage {
  overflow: hidden;
}

.insight-chart-cursor {
  position: absolute;
  z-index: 4;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--ink);
  opacity: 0.26;
  pointer-events: none;
}

.insight-chart-tooltip-anchor {
  position: absolute;
  z-index: 5;
  top: 8px;
  transform: translateX(-50%);
  pointer-events: none;
}

.insight-chart-tooltip {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 5px 9px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  color: var(--tooltip-fg);
  background: var(--tooltip-bg);
  box-shadow: var(--shadow-overlay);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.insight-chart-tooltip-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.insight-chart-tooltip-dot {
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 50%;
}

/* Status pills share the same base-hue → color-mix derivation as .records-tag,
 * so both components stay consistent across light and dark. */
.filter-status-todo {
  --tag-base: oklch(0.757 0.153 66.401);
}
.filter-status-progress {
  --tag-base: oklch(0.671 0.118 219.351);
}
.filter-status-done {
  --tag-base: oklch(0.652 0.131 162.865);
}

.filter-status-todo,
.filter-status-progress,
.filter-status-done {
  color: color-mix(in srgb, var(--tag-base) 92%, var(--ink));
  background: color-mix(in srgb, var(--tag-base) 20%, var(--surface));
  border-color: color-mix(in srgb, var(--tag-base) 34%, var(--surface));
}

/* Dark mode — a richer, saturated same-hue fill
 * with bright same-hue text and no visible border (light mode keeps the soft
 * tinted pastels above). Applies to both the records grid and status pills. */
.dark .records-tag,
.dark .filter-status-todo,
.dark .filter-status-progress,
.dark .filter-status-done {
  color: color-mix(in srgb, var(--tag-base) 86%, white);
  background: color-mix(in srgb, var(--tag-base) 34%, var(--surface));
  border-color: color-mix(in srgb, var(--tag-base) 34%, var(--surface));
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes eq-bounce {
  0%,
  100% {
    transform: scaleY(0.35);
  }
  50% {
    transform: scaleY(1);
  }
}

/* ── StreamText primitive ─────────────────────────────────
 * Fast character reveal: the newest few characters carry a
 * soft, masked blur so the leading edge resolves smoothly as
 * text flows in. The caret holds solid while streaming, then
 * blinks once the string settles. */
/* ══════════════════════════════════════════════════════════
 * COMPONENT-SPECIFIC — StreamText
 * The streaming caret + tail.
 * Copy this block only alongside StreamText; it is not part of the
 * generic foundation above.
 * ══════════════════════════════════════════════════════════ */
.stream-tail {
  filter: blur(1.6px);
  -webkit-mask-image: linear-gradient(to right, oklch(0 0 0) 20%, oklch(0 0 0 / 0.2));
  mask-image: linear-gradient(to right, oklch(0 0 0) 20%, oklch(0 0 0 / 0.2));
}

.stream-caret {
  display: inline-block;
  width: 2px;
  height: 1.05em;
  margin-left: 1.5px;
  translate: 0 -0.5px;
  border-radius: 1px;
  background: var(--ink);
  vertical-align: text-bottom;
  animation: caret-blink 1s step-end infinite;
}

.stream-caret.is-streaming {
  animation: none;
}

@keyframes caret-blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .stream-caret {
    animation: none;
  }
  .stream-tail {
    filter: none;
    -webkit-mask-image: none;
    mask-image: none;
  }
}

@keyframes pop-in {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

/* pixel-grid loader — brighten plateau, staggered per cell */
@keyframes pixel-on {
  0%, 100% {
    opacity: 0.15;
  }
  18%, 42% {
    opacity: 1;
  }
  62% {
    opacity: 0.15;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* The upstream tokens are local copies; no parent repository is needed. */
:root { --font-inter: 'Inter Variable'; --font-mono-face: 'JetBrains Mono Variable'; }
body { margin: 0; color: var(--ink); font-family: var(--font-inter), system-ui, "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", sans-serif; }
a, button, summary { -webkit-tap-highlight-color: transparent; }
a.router-link-exact-active { color: var(--ink); }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 4px; }

html[lang="zh-CN"] { letter-spacing: 0; }
html[lang="zh-CN"] body { letter-spacing: 0; }
